{
  "attribute_types": {
    "user_id": "INTEGER",
    "password_setting_date": "TIMESTAMP",
    "password_history_id": "INTEGER",
    "salted_password_hash": "TEXT",
    "password_salt": "TEXT"
  },
  "functional_dependencies": [
    "[user_id, password_setting_date] -> []",
    "[password_history_id] -> [user_id, salted_password_hash, password_salt, password_setting_date]"
  ]
}

